const fs = require('fs');
const http = require('http');

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function main(){
  const list = await (await fetch('http://127.0.0.1:9229/json/list')).json();
  const page = list.find(x => x.type === 'page');
  if(!page) throw new Error('no page target');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res,rej)=>{ws.onopen=res;ws.onerror=rej;});
  let id=0; const pending=new Map();
  ws.onmessage = ev => {
    const m=JSON.parse(ev.data);
    if(m.id && pending.has(m.id)){
      const {res,rej}=pending.get(m.id); pending.delete(m.id);
      if(m.error) rej(new Error(JSON.stringify(m.error))); else res(m.result);
    }
  };
  const send=(method,params={})=>new Promise((res,rej)=>{const n=++id;pending.set(n,{res,rej});ws.send(JSON.stringify({id:n,method,params}));});

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride',{width:1080,height:1920,deviceScaleFactor:1,mobile:false,screenWidth:1080,screenHeight:1920});
  const t0=Date.now();
  await send('Page.navigate',{url:'http://127.0.0.1:8899/video.html'});
  for(let i=0;i<100;i++){
    await sleep(100);
    const r=await send('Runtime.evaluate',{expression:'window.__ready===true',returnByValue:true});
    if(r.result.value) break;
    if(i===99) throw new Error('not ready');
  }
  console.log('loaded ms',Date.now()-t0);
  await send('Runtime.evaluate',{expression:'document.fonts.ready.then(()=>true)',awaitPromise:true,returnByValue:true});
  await send('Runtime.evaluate',{expression:'window.renderAt(12)',returnByValue:true});
  await send('Runtime.evaluate',{expression:'new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>r(true))))',awaitPromise:true,returnByValue:true});
